#include <bits/stdc++.h>
#define MAXN 150
using namespace std;
typedef long long ll;
typedef pair<int,int> pii;

struct FlowEdge {
    int to, rev;
    ll cap;
    FlowEdge(int t, int r, ll c) : to(t), rev(r), cap(c) {}
};

class MaxFlow {
    int n, s, t;
    vector<vector<FlowEdge>> adj;
    vector<int> dist, ptr;
public:
    MaxFlow(int n, int s, int t) : n(n), s(s), t(t) { adj.resize(n); dist.resize(n); ptr.resize(n); }
    void addEdge(int u, int v, ll c) {
        adj[u].emplace_back(v, (int)adj[v].size(), c);
        adj[v].emplace_back(u, (int)adj[u].size()-1, 0);
    }
    bool bfs() {
        fill(dist.begin(), dist.end(), -1);
        queue<int> q;
        dist[s] = 0; q.push(s);
        while(!q.empty()) {
            int u = q.front(); q.pop();
            for(auto &e : adj[u]) if(e.cap > 0 && dist[e.to] == -1) {
                dist[e.to] = dist[u] + 1;
                q.push(e.to);
            }
        }
        return dist[t] != -1;
    }
    ll dfs(int u, ll f) {
        if(u == t) return f;
        for(int &i = ptr[u]; i < (int)adj[u].size(); ++i) {
            auto &e = adj[u][i];
            if(e.cap > 0 && dist[e.to] == dist[u] + 1) {
                ll ret = dfs(e.to, min(f, e.cap));
                if(ret) {
                    e.cap -= ret;
                    adj[e.to][e.rev].cap += ret;
                    return ret;
                }
            }
        }
        return 0;
    }
    ll maxflow() {
        ll ans = 0;
        while(bfs()) {
            fill(ptr.begin(), ptr.end(), 0);
            while(ll f = dfs(s, 1e18)) ans += f;
        }
        return ans;
    }
};

int pos[MAXN][MAXN], tMat[MAXN][MAXN], aMat[MAXN][MAXN];

void fillT(int i, int j, vector<string>& sc, int n, int cur) {
    if(i<0||i>=n||j<0||j>=n) return;
    if(!isdigit(sc[i][j]) && sc[i][j]!='Z') return;
    if(tMat[i][j]!=-1 && tMat[i][j]<=cur) return;
    tMat[i][j] = (tMat[i][j]==-1)?cur:min(tMat[i][j],cur);
    fillT(i+1,j,sc,n,cur+1);
    fillT(i-1,j,sc,n,cur+1);
    fillT(i,j+1,sc,n,cur+1);
    fillT(i,j-1,sc,n,cur+1);
}

void fillA(int i, int j, vector<string>& sc, int n, int cur) {
    if(i<0||i>=n||j<0||j>=n) return;
    if(!isdigit(sc[i][j])) return;
    if(aMat[i][j]!=-1 && aMat[i][j]<=cur) return;
    aMat[i][j] = (aMat[i][j]==-1)?cur:min(aMat[i][j],cur);
    fillA(i+1,j,sc,n,cur+1);
    fillA(i-1,j,sc,n,cur+1);
    fillA(i,j+1,sc,n,cur+1);
    fillA(i,j-1,sc,n,cur+1);
}

int main() {
    ios::sync_with_stdio(0); cin.tie(0);
    int n, t;
    cin >> n >> t;
    int n2 = n*n;
    int total = n2*2 + 2;
    MaxFlow mf(total, 0, total-1);
    vector<string> sc(n), caps(n);
    int cnt = 1;
    for(int i=0;i<n;i++) for(int j=0;j<n;j++) pos[i][j] = cnt++;
    int zi=0,zj=0;
    for(int i=0;i<n;i++) {
        cin >> sc[i];
        for(int j=0;j<n;j++) if(sc[i][j]=='Z') { zi=i; zj=j; }
    }
    for(int i=0;i<n;i++) cin >> caps[i];
    memset(tMat, -1, sizeof(tMat));
    fillT(zi,zj,sc,n,0);
    for(int i=0;i<n;i++) for(int j=0;j<n;j++) if(tMat[i][j]==-1 && isdigit(sc[i][j])) tMat[i][j] = t;
    for(int i=0;i<n;i++) for(int j=0;j<n;j++) {
        if(isdigit(sc[i][j])) {
            int lim = sc[i][j]-'0';
            mf.addEdge(0, pos[i][j], lim);
            memset(aMat, -1, sizeof(aMat));
            fillA(i,j,sc,n,0);
            for(int k=0;k<n;k++) for(int l=0;l<n;l++) {
                if(aMat[k][l]!=-1 && tMat[k][l]!=-1 && aMat[k][l]<=tMat[k][l] && aMat[k][l]<=t) {
                    bool ok = true;
                    if(aMat[k][l]==tMat[k][l]) {
                        ok = false;
                        if(k+1<n && aMat[k+1][l]!=-1 && aMat[k+1][l]<tMat[k+1][l]) ok=true;
                        if(k-1>=0 && aMat[k-1][l]!=-1 && aMat[k-1][l]<tMat[k-1][l]) ok=true;
                        if(l+1<n && aMat[k][l+1]!=-1 && aMat[k][l+1]<tMat[k][l+1]) ok=true;
                        if(l-1>=0 && aMat[k][l-1]!=-1 && aMat[k][l-1]<tMat[k][l-1]) ok=true;
                    }
                    if(ok) mf.addEdge(pos[i][j], n2+pos[k][l], lim);
                }
            }
        }
    }
    for(int i=0;i<n;i++) for(int j=0;j<n;j++) if(isdigit(caps[i][j])) mf.addEdge(n2+pos[i][j], total-1, caps[i][j]-'0');
    cout << mf.maxflow() << '\n';
    return 0;
}
